Predictable state container for JavaScript apps, centralizing application state.

```javascript
import { createStore } from 'redux';

const store = createStore(reducer);
```

Plain object describing what happened.

```javascript
const addTodoAction = {
  type: 'ADD_TODO',
  payload: {
    id: 1,
    text: 'Learn Redux'
  }
};
```

Function that creates and returns an action.

```javascript
const addTodo = (text) => ({
  type: 'ADD_TODO',
  payload: { id: Date.now(), text }
});

dispatch(addTodo('Learn Redux'));
```

Pure function that takes previous state and action, returns new state.

```javascript
function todosReducer(state = [], action) {
  switch (action.type) {
    case 'ADD_TODO':
      return [...state, action.payload];
    case 'REMOVE_TODO':
      return state.filter(todo => todo.id !== action.payload);
    default:
      return state;
  }
}
```

Function to send actions to the store.

```javascript
store.dispatch({ type: 'INCREMENT' });
store.dispatch(addTodo('Learn Redux'));
```

Method to listen to state changes.

```javascript
const unsubscribe = store.subscribe(() => {
  console.log('State changed:', store.getState());
});

unsubscribe(); // stop listening
```

Combines multiple reducers into single root reducer.

```javascript
import { combineReducers } from 'redux';

const rootReducer = combineReducers({
  todos: todosReducer,
  user: userReducer,
  posts: postsReducer
});
```

Functions that intercept actions before they reach reducers.

```javascript
const logger = store => next => action => {
  console.log('dispatching', action);
  const result = next(action);
  console.log('next state', store.getState());
  return result;
};
```

Middleware allowing action creators to return functions instead of objects (for async operations).

```javascript
const fetchUser = (id) => {
  return async (dispatch) => {
    dispatch({ type: 'FETCH_USER_START' });
    try {
      const user = await api.getUser(id);
      dispatch({ type: 'FETCH_USER_SUCCESS', payload: user });
    } catch (error) {
      dispatch({ type: 'FETCH_USER_ERROR', payload: error });
    }
  };
};
```

Middleware using generator functions for side effects.

```javascript
function* fetchUserSaga(action) {
  try {
    const user = yield call(api.getUser, action.payload);
    yield put({ type: 'FETCH_USER_SUCCESS', payload: user });
  } catch (error) {
    yield put({ type: 'FETCH_USER_ERROR', payload: error });
  }
}
```

HOC connecting React component to Redux store.

```javascript
import { connect } from 'react-redux';

const mapStateToProps = (state) => ({
  todos: state.todos
});

const mapDispatchToProps = {
  addTodo
};

export default connect(mapStateToProps, mapDispatchToProps)(TodoList);
```

Function selecting which parts of state component needs.

```javascript
const mapStateToProps = (state, ownProps) => ({
  todo: state.todos.find(t => t.id === ownProps.id),
  user: state.user
});
```

Maps action creators to component props.

```javascript
const mapDispatchToProps = (dispatch) => ({
  addTodo: (text) => dispatch(addTodo(text)),
  removeTodo: (id) => dispatch(removeTodo(id))
});

// or shorthand
const mapDispatchToProps = {
  addTodo,
  removeTodo
};
```

Hook to extract data from Redux store.

```javascript
import { useSelector } from 'react-redux';

function TodoList() {
  const todos = useSelector(state => state.todos);
  const user = useSelector(state => state.user);
  return <div>{/* render todos */}</div>;
}
```

Hook to get dispatch function.

```javascript
import { useDispatch } from 'react-redux';

function AddTodo() {
  const dispatch = useDispatch();

  const handleAdd = (text) => {
    dispatch(addTodo(text));
  };

  return <button onClick={() => handleAdd('New Todo')}>Add</button>;
}
```

Hook to access Redux store directly (rarely needed).

```javascript
import { useStore } from 'react-redux';

function Component() {
  const store = useStore();
  console.log(store.getState());
}
```

Official recommended way to write Redux logic.

```javascript
import { configureStore, createSlice } from '@reduxjs/toolkit';

const todosSlice = createSlice({
  name: 'todos',
  initialState: [],
  reducers: {
    addTodo: (state, action) => {
      state.push(action.payload); // RTK uses Immer
    }
  }
});
```

RTK function creating reducer and action creators automatically.

```javascript
const counterSlice = createSlice({
  name: 'counter',
  initialState: { value: 0 },
  reducers: {
    increment: state => { state.value += 1; },
    decrement: state => { state.value -= 1; },
    incrementByAmount: (state, action) => {
      state.value += action.payload;
    }
  }
});

export const { increment, decrement, incrementByAmount } = counterSlice.actions;
```

RTK function simplifying store setup.

```javascript
import { configureStore } from '@reduxjs/toolkit';

const store = configureStore({
  reducer: {
    todos: todosReducer,
    user: userReducer
  }
  // automatically adds thunk middleware and dev tools
});
```

RTK function for async operations.

```javascript
import { createAsyncThunk } from '@reduxjs/toolkit';

const fetchUser = createAsyncThunk(
  'user/fetch',
  async (userId) => {
    const response = await api.getUser(userId);
    return response.data;
  }
);

// Automatically creates pending, fulfilled, rejected actions
```

Handle actions defined outside the slice (like async thunks).

```javascript
const userSlice = createSlice({
  name: 'user',
  initialState: { data: null, loading: false },
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchUser.pending, (state) => {
        state.loading = true;
      })
      .addCase(fetchUser.fulfilled, (state, action) => {
        state.data = action.payload;
        state.loading = false;
      })
      .addCase(fetchUser.rejected, (state) => {
        state.loading = false;
      });
  }
});
```

Creates memoized selectors for derived data.

```javascript
import { createSelector } from '@reduxjs/toolkit';

const selectTodos = state => state.todos;
const selectFilter = state => state.filter;

const selectFilteredTodos = createSelector(
  [selectTodos, selectFilter],
  (todos, filter) => {
    return todos.filter(todo => todo.status === filter);
  }
);
```

Organizing state by IDs to avoid duplication and nesting.

```javascript
// Bad
const state = {
  posts: [
    { id: 1, author: { id: 5, name: 'John' } },
    { id: 2, author: { id: 5, name: 'John' } } // duplicated
  ]
};

// Good (normalized)
const state = {
  posts: {
    byId: {
      1: { id: 1, authorId: 5 },
      2: { id: 2, authorId: 5 }
    },
    allIds: [1, 2]
  },
  authors: {
    byId: {
      5: { id: 5, name: 'John' }
    }
  }
};
```

RTK utility for normalized CRUD operations.

```javascript
import { createEntityAdapter, createSlice } from '@reduxjs/toolkit';

const todosAdapter = createEntityAdapter();

const todosSlice = createSlice({
  name: 'todos',
  initialState: todosAdapter.getInitialState(),
  reducers: {
    todoAdded: todosAdapter.addOne,
    todosReceived: todosAdapter.setAll,
    todoUpdated: todosAdapter.updateOne,
    todoRemoved: todosAdapter.removeOne
  }
});
```

Library allowing "mutative" code that produces immutable updates.

```javascript
const slice = createSlice({
  name: 'todos',
  initialState: [],
  reducers: {
    addTodo: (state, action) => {
      // looks like mutation, actually immutable
      state.push(action.payload);
    }
  }
});
```

Browser extension for debugging Redux applications.

```javascript
const store = configureStore({
  reducer: rootReducer
  // DevTools automatically enabled with RTK
});
```

Library persisting and rehydrating Redux store (localStorage, AsyncStorage).

```javascript
import { persistStore, persistReducer } from 'redux-persist';
import storage from 'redux-persist/lib/storage';

const persistConfig = {
  key: 'root',
  storage
};

const persistedReducer = persistReducer(persistConfig, rootReducer);
const store = configureStore({ reducer: persistedReducer });
const persistor = persistStore(store);
```

Common pattern: 'domain/eventName'

```javascript
const ADD_TODO = 'todos/add';
const REMOVE_TODO = 'todos/remove';
const FETCH_USER_SUCCESS = 'user/fetchSuccess';
```

Data sent with action.

```javascript
{
  type: 'ADD_TODO',
  payload: {
    id: 1,
    text: 'Learn Redux',
    completed: false
  }
}
```

Using middleware like Redux Thunk, Redux Saga, or Redux-Observable.

```javascript
// Thunk
const fetchData = () => async (dispatch) => {
  const data = await api.fetch();
  dispatch({ type: 'DATA_RECEIVED', payload: data });
};
```

Function to add middleware to Redux store.

```javascript
import { createStore, applyMiddleware } from 'redux';
import thunk from 'redux-thunk';

const store = createStore(
  rootReducer,
  applyMiddleware(thunk, logger)
);
```

Wraps action creators in dispatch calls.

```javascript
import { bindActionCreators } from 'redux';

const boundActions = bindActionCreators(
  { addTodo, removeTodo },
  dispatch
);

boundActions.addTodo('text'); // automatically dispatched
```

Redux uses shallow comparison to determine if state changed.

```javascript
// These trigger re-render
state = { ...state, newProp: value };
state.array = [...state.array, newItem];

// This doesn't (same reference)
state.prop = newValue; // don't mutate!
```

Constants defining action types to avoid typos.

```javascript
// constants.js
export const ADD_TODO = 'ADD_TODO';
export const REMOVE_TODO = 'REMOVE_TODO';

// usage
import { ADD_TODO } from './constants';

const action = { type: ADD_TODO, payload: todo };
```

Breaking reducer logic into smaller, focused reducers.

```javascript
function visibilityFilter(state = 'SHOW_ALL', action) {
  switch (action.type) {
    case 'SET_FILTER':
      return action.payload;
    default:
      return state;
  }
}

function todos(state = [], action) {
  // handle todo actions
}

const rootReducer = combineReducers({
  visibilityFilter,
  todos
});
```

State value before any actions are dispatched.

```javascript
const initialState = {
  todos: [],
  filter: 'SHOW_ALL',
  loading: false
};

function reducer(state = initialState, action) {
  // ...
}
```

Updating reducers without losing state.

```javascript
if (module.hot) {
  module.hot.accept('./reducers', () => {
    store.replaceReducer(require('./reducers').default);
  });
}
```
